CREATE DATABASE IF NOT EXISTS menubuilder CHARACTER SET utf8mb4;
USE menubuilder;
CREATE TABLE restaurants(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(30) NOT NULL UNIQUE,whatsapp VARCHAR(15) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,restaurant_id INT NOT NULL,name VARCHAR(60) NOT NULL,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE items(id INT AUTO_INCREMENT PRIMARY KEY,restaurant_id INT NOT NULL,category_id INT NOT NULL,name VARCHAR(100) NOT NULL,description VARCHAR(255) DEFAULT '',price DECIMAL(10,2) NOT NULL,image VARCHAR(40) NULL,available TINYINT(1) DEFAULT 1,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
